import java.io.*;
import java.util.*;
import static java.lang.System.out;


public class Solution{
    private static class Scan{
        StringTokenizer str;
        BufferedReader br;
        Scan() {
            br = new BufferedReader(new InputStreamReader(System.in));
            str = null;
        }
        Scan(InputStream x)
        {
            br=new BufferedReader(new InputStreamReader(x));
            str=null;
        }
        String next()
        {
            while(str==null||!str.hasMoreElements()){
                try{
                    str=new StringTokenizer(br.readLine());
                }catch (Exception e){
                    out.println(e);
                }
            }
            return str.nextToken();
        }
        int nextInt()
        {
            return Integer.parseInt(next());
        }
        long nextLong()
        {
            return  Long.parseLong(next());
        }
        double nextDouble()
        {
            return Double.parseDouble(next());
        }
        String nextLine()
        {
            try {
                if (str == null || !str.hasMoreElements())str=new StringTokenizer(br.readLine());
            }catch (IOException e){
                out.println(e);
            }
            return str.nextToken("\n");
        }
    }
    static long MOD=998244353L;
    static int asz=200005;
    static long BigMod(long a,long b,long m){
        if(b==0)return 1L;
        if(b%2==1)return a*BigMod(a,b-1,m)%m;
        return BigMod(a*a%m,b/2,m)%m;
    }
    static long f[]=new long[asz];
    static long C(int n,int k){
        if(k>n)return 0L;
        return f[n]*BigMod(f[k],MOD-2,MOD)%MOD*BigMod(f[n-k],MOD-2,MOD)%MOD;
    }
    static long solve(int n,int k){
        long ans=0;
        for(int i=0;i<=n-k;i++){
            if(i%2==0)ans=(ans+C(n-k,i)*BigMod(n-k-i,n,MOD)%MOD)%MOD;
            else ans=(ans-C(n-k,i)*BigMod(n-k-i,n,MOD)%MOD+MOD)%MOD;
        }
        return ans;
    }
    public static void main(String[] args){
        Scan in=new Scan();
        int t=1;
        //t=in.nextInt();
        for(int qq=1;qq<=t;qq++){
            long n,k;
            n=in.nextLong();
            k=in.nextLong();
            f[0]=1;
            for(long i=1;i<=n;i++)f[(int)i]=f[(int)(i-1)]*i%MOD;
            if(k>=n)out.println(0);
            else if(k==0)out.println(f[(int)n]);
            else{
                out.println(2*C((int)n,(int)(n-k))*solve((int)n,(int)k)%MOD);
            }
        }
    }
}
